// ---------- REGIME BANNER (from squeeze-pretrigger) ----------
const regEl=document.getElementById("regime");
if(pre){
  const cls=stClean(pre.state);
  regEl.innerHTML=`
    <div class="stateBox st-${cls}">
      <div class="label">Squeeze Regime</div>
      <div class="name">${esc(pre.state||"—")}</div>
      <div class="strength">SIGNAL ${pre.signal_strength||0}/100</div>
    </div>
    <div class="desc">
      ${esc(pre.state_description||"")}
      <div class="meta">As of ${fmtDate(pre.as_of)} · Engine v${esc(pre.version||"?")} · Prev state: ${esc(pre.previous_state||"—")}</div>
    </div>`;
} else {
  regEl.innerHTML=`<div class="empty" style="grid-column:1/-1">Squeeze pre-trigger feed unavailable.</div>`;
}

// ---------- 4 KPIs ----------
const k=[];
if(pre){
  const s=pre.summary||{};
  k.push(["Imminent (5/5)",s.n_imminent_5of5||0,"all 5 conditions firing","red"]);
  k.push(["Pre-Trigger (4/5)",s.n_pretrigger_4of5||0,"4 of 5 conditions","orange"]);
  k.push(["Early (3/5)",s.n_early_3of5||0,"3 of 5 conditions","yellow"]);
  k.push(["Evaluated",s.n_candidates_evaluated||0,"universe scanned today","cyan"]);
} else if(si){
  const n=Object.keys(si.by_ticker||{}).length;
  k.push(["Crowded Shorts",(si.top_crowded_shorts||[]).length,"tracked","red"]);
  k.push(["High DTC",(si.top_high_dtc||[]).length,"tracked","orange"]);
  k.push(["Squeeze Risk",(si.top_squeeze_risk||[]).length,"tracked","yellow"]);
  k.push(["SI Collapse·Flat",(si.top_si_collapse_flat_price||[]).length,"#19","green"]);
  k.push(["Names With Data",n,"FINRA + Polygon","cyan"]);
}
document.getElementById("kpis").innerHTML=k.length?
  k.map(([t,v,s,c])=>`<div class="card ${c}"><h3>${esc(t)}</h3><div class="big">${v}</div><div class="sub">${esc(s)}</div></div>`).join("")
  :`<div class="card" style="grid-column:1/-1"><div class="empty">No KPI feeds available.</div></div>`;

// ---------- SETUP LEADERBOARDS (Imminent + Pre-trigger + Early merged) ----------
const boardEl=document.getElementById("boardSetups");
const allSetups=[].concat(pre?.imminent_setups||[],pre?.pretrigger_setups||[],pre?.early_setups||[]).slice(0,30);
if(allSetups.length){
  let h=`<table><thead><tr>
    <th>Ticker</th><th>Sector</th><th class="num">Mcap</th>
    <th class="num">Price</th><th class="num">20d Δ</th>
    <th class="num">SI%</th><th class="num">DTC</th><th class="num">Util%</th><th class="num">Z</th>
    <th>Conditions</th><th class="num">Score</th><th>Setup</th>
  </tr></thead><tbody>`;
  for(const r of allSetups){
    const c=r.conditions||{};
    const sc=r.score_components||{};
    const flags=[
      cflag(c["si_float_>18pct"],"SI/float >18%"),
      cflag(c["dtc_>6"],"Days-to-cover >6"),
      cflag(c["util_>80pct"],"FINRA util >80%"),
      cflag(c["z_score_>0.5"],"Z-score >+0.5"),
      cflag(c["catalyst_30d"],"Catalyst 30d"),
    ].join("");
    const runup=r.recent_runup_20d_pct;
    const rcol=runup>=20?"var(--red)":runup>=10?"var(--orange)":runup<0?"var(--green)":"var(--mute)";
    const strength=r.signal_strength||0;
    const sbcol=strength>=80?"var(--red)":strength>=60?"var(--orange)":"var(--yellow)";
    h+=`<tr>
      <td class="tk">${esc(r.ticker)}<span class="nm">${esc(r.name||"")}</span></td>
      <td style="color:var(--dim)">${esc(r.sector||"")}</td>
      <td class="num">${fmtMcap(r.mcap_usd)}</td>
      <td class="num">${fmtUSD(r.price_usd)}</td>
      <td class="num" style="color:${rcol}">${runup>0?"+":""}${fmtPct(runup,1)}</td>
      <td class="num">${fmtPct(sc.si_pct_float,1)}</td>
      <td class="num">${fmtNum(sc.days_to_cover,1)}</td>
      <td class="num">${fmtPct(sc.short_utilization,0)}</td>
      <td class="num">${fmtZ(sc.z_score)}</td>
      <td><div class="cflags">${flags}</div></td>
      <td class="num" style="color:${sbcol};font-weight:700">${strength}</td>
      <td><span class="pill p-${r.setup_quality}">${esc(r.setup_quality||"")}</span></td>
    </tr>`;
  }
  boardEl.innerHTML=h+`</tbody></table>`;
} else {
  boardEl.innerHTML=`<div class="empty">
    <b style="color:var(--mute)">No setups today.</b><br>
    Pre-trigger engine evaluated ${pre?.summary?.n_candidates_evaluated||0} candidates and found 0 with 3+/5 conditions. <br>
    Squeeze regimes cluster; this is a normal QUIET window between waves. <br>
    Check the leaderboards below for early positioning.
  </div>`;
}

// Squeeze forecast stays unavailable for both legacy and research packets.
document.getElementById("regime").innerHTML=window.JHSqueezeResearch?.render(pre)||'<p>Squeeze research unavailable. Forecast and trade withheld.</p>';
document.getElementById("kpis").innerHTML=['Squeeze probability','Expected return','Position size','Qualifying setups'].map(label=>'<div class="card"><h3>'+label+'</h3><div class="big">Unavailable</div><div class="sub">Qualification incomplete</div></div>').join('');
document.getElementById("boardSetups").textContent='No qualified setup count or leaderboard is available. This does not establish an empty opportunity set or a quiet market.';

document.getElementById("why").innerHTML=pre?.why_now_explainer?
  "<b>What this is.</b> "+esc(pre.why_now_explainer).replace(/\n\n/g,"<br><br>").replace(/^### .+\n+/g,"").replace(/\n/g," ")+
  "<br><br><b>Sources:</b> "+(pre.sources||[]).map(esc).join(" · ")
  :"";
document.getElementById("why").textContent='Pre-trigger inputs are retained for audit and descriptive research. Source identity, freshness, float/borrow data and out-of-sample forecasts require qualification before investment use.';

function renderSqueeze(d) {
  if (!d) return '<div class="error">Engine offline.</div>';
  const imm = d.imminent_setups || [];
  const pre = d.pretrigger_setups || [];
  const early = d.early_setups || [];
  const all = [...imm, ...pre, ...early];
  const exp = d.forward_expectations || {};
  let h = `
    <div class="kpi-row">
      <div class="kpi"><div class="kpi-label">Imminent (5/5)</div><div class="kpi-value gold">${imm.length}</div></div>
      <div class="kpi"><div class="kpi-label">Pre-Trigger (4/5)</div><div class="kpi-value cyan">${pre.length}</div></div>
      <div class="kpi"><div class="kpi-label">Early (3/5)</div><div class="kpi-value">${early.length}</div></div>
      <div class="kpi"><div class="kpi-label">2m exp.</div><div class="kpi-value gold">+${exp['2m'] ?? '-'}%</div></div>
    </div>`;
  if (all.length) {
    h += `<table class="setup-table"><thead><tr><th>Tkr</th><th>Quality</th><th>SI/F</th><th>DTC</th><th>Util</th><th>Catalyst</th><th></th></tr></thead><tbody>`;
    all.slice(0,15).forEach((r,i)=>{
      const id = `sqz-${i}`;
      const cat = r.catalysts_30d && r.catalysts_30d[0];
      h += `<tr id="${id}" class="row-clickable" onclick="toggleRow('${id}', \`${renderTicketDetails(r.trade_ticket).replace(/`/g,'').replace(/\\/g,'')}\`)">
        <td class="ticker-cell">${r.ticker}</td>
        <td>${r.setup_quality}</td>
        <td>${r.score_components?.si_pct_float?.toFixed(0)}%</td>
        <td>${r.score_components?.days_to_cover?.toFixed(1)}</td>
        <td>${r.score_components?.short_utilization?.toFixed(0)}%</td>
        <td style="font-size:10px;color:var(--muted)">${cat ? `${cat.type} in ${cat.dte}d` : '-'}</td>
        <td style="color:var(--muted);font-size:10px">click</td>
      </tr>`;
    });
    h += `</tbody></table>`;
  } else h += '<div class="empty">No qualifying setups today.</div>';
  if (d.why_now_explainer) h += `<div class="why-now"><h4>Why Now</h4>${d.why_now_explainer.replace(/\*\*/g,'').replace(/###/g,'').replace(/\n\n/g,'<br><br>')}</div>`;
  return h;
}
function renderSqueeze(d) {
  return window.JHSqueezeResearch?.render(d)||'<div class="empty">Squeeze research unavailable. Forecast and trade withheld.</div>';
}

function renderSqueeze(d) {
  var p = d && d.sqz || {};
  var r = p.row;
  var doc = p.doc || {};
  var note = "<div class=note>Crowding / borrow / short pressure. Estimate of exit difficulty, not a squeeze clock. State: " + esc(doc.state || "—") + "</div>";
  if (!r) return note + "<div class=empty>No squeeze-pretrigger row for this symbol today.</div>";
  return note + "<div class=kpi>" + [
    kpi("Score", fmt(num(r.score))),
    kpi("Ticker", esc(r.ticker || "—")),
    kpi("Posture", esc(r.posture || r.tag || "—"))
  ].join("") + "</div>";
}
function renderSqueeze(d) {
  return "<div class=note>Squeeze forecasts, borrow pressure and exit difficulty are unqualified. WAIT means abstain.</div><div class=empty>No qualified squeeze score or trade is available for this symbol. Missing context does not mean zero risk or no setups. <a href='/squeeze.html'>Open source research and limitations</a>.</div>";
}
